        <motion.div initial={{opacity:0,scale:.96}} animate={{opacity:1,scale:1}} transition={{duration:.8,delay:.15}} className="relative"><div className="rounded-3xl border border-white/15 bg-white/[.09] p-3 shadow-2xl backdrop-blur-lg"><div className="overflow-hidden rounded-2xl bg-[#f1f6f7]"><div className="flex items-center justify-between border-b border-[#dbe6e9] bg-white px-4 py-3"><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#2E7D32]"></span><span className="text-xs font-bold text-[#0A2540]">LIVE SITUATION ROOM</span></div><span className="font-mono text-[10px] text-slate-500">IND-DEL / 14:32:08</span></div><div className="relative h-[300px] overflow-hidden bg-[#dce9e7] grid-paper"><div className="absolute inset-0 opacity-40 [background-image:linear-gradient(125deg,transparent_48%,#9cbab5_49%,#9cbab5_50%,transparent_51%),linear-gradient(55deg,transparent_48%,#9cbab5_49%,#9cbab5_50%,transparent_51%)]"></div><div className="absolute left-[38%] top-[27%] h-24 w-24 rounded-full border border-orange-500/30 bg-orange-500/10 animate-pulse-ring"></div><span className="absolute left-[45%] top-[39%] h-3 w-3 rounded-full bg-[#FF6B00] ring-4 ring-orange-500/20"></span><span className="absolute left-[24%] top-[55%] h-3 w-3 rounded-full bg-[#2E7D32] ring-4 ring-green-500/20"></span><span className="absolute left-[69%] top-[60%] h-3 w-3 rounded-full bg-[#3979a6] ring-4 ring-sky-500/20"></span><div className="absolute bottom-3 left-3 rounded-lg bg-white/85 px-3 py-2 text-[10px] text-[#0A2540] shadow-sm"><b>ACTIVE ZONE</b><br/><span className="text-slate-500">Yamuna floodplain · 18 signals</span></div></div><div className="grid grid-cols-3 gap-2 bg-white p-3"><div className="rounded-lg bg-[#fff3e8] p-2"><p className="text-[10px] text-slate-500">Survivors</p><b className="font-serif text-lg text-[#d95700]">47</b></div><div className="rounded-lg bg-[#edf7ef] p-2"><p className="text-[10px] text-slate-500">Teams active</p><b className="font-serif text-lg text-[#2E7D32]">12</b></div><div className="rounded-lg bg-[#eff5f8] p-2"><p className="text-[10px] text-slate-500">ETA median</p><b className="font-serif text-lg text-[#3979a6]">08m</b></div></div></div></div><div className="absolute -bottom-5 -left-5 flex items-center gap-3 rounded-2xl border border-white/20 bg-[#123b60] p-3 shadow-xl"><span className="grid h-9 w-9 place-items-center rounded-lg bg-[#2E7D32] text-white"><Check size={17}/></span><div><p className="text-xs font-bold">Situation updated</p><p className="text-[10px] text-slate-300">18 new signals processed</p></div></div></motion.div>
